  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    return {valid: false, error: `${type} before must be a cursor object`};
  }
  const cursor = value as Record<string, unknown>;
  if (typeof cursor.sessionId !== 'string' || cursor.sessionId.length < 1 || cursor.sessionId.length > 128) {
    return {valid: false, error: `${type} before.sessionId must be 1-128 characters`};
  }
  if (!validDate(cursor.updatedAt)) {
    return {valid: false, error: `${type} before.updatedAt must be a valid date`};
  }
  return {valid: true, updatedAt: cursor.updatedAt as string | number, sessionId: cursor.sessionId};
}

function isValidDate(value: unknown): boolean {
  if (typeof value === 'string') return Number.isFinite(Date.parse(value));
  if (typeof value === 'number') return Number.isFinite(value) && Number.isFinite(new Date(value).getTime());
  return false;
}
